# llm_clients.py
from openai import OpenAI
from core.ai_provider import ProviderError

def call_qwen3_coder_text(prompt, model="Qwen3-Coder", **kwargs):
    base_url = "VLLM_QWEN3_CODER_BASE_URL"
    api_key = "VLLM_QWEN3_CODER_API_KEY"
    
    client = OpenAI(
        base_url=base_url,
        api_key=api_key
    )
    
    try:
        response = client.chat.completions.create(
            model=model,
            messages=[{"role": "user", "content": prompt}],
            **kwargs
        )
        return response.choices[0].message.content
    except Exception as e:
        raise ProviderError(f"Qwen3 Coder API error: {str(e)}")

