from urllib.request import Request, urlopen
from urllib.error import URLError

def check_qwen3_coder_available():
    base_url = "VLLM_QWEN3_CODER_BASE_URL"
    api_key = "VLLM_QWEN3_CODER_API_KEY"
    
    if not base_url or not api_key:
        return False
    
    try:
        req = Request(f"{base_url}/health")
        req.add_header("Authorization", f"Bearer {api_key}")
        urlopen(req, timeout=5)
        return True
    except URLError:
        return False

register_provider(
    name="qwen3_coder_text",
    func=call_qwen3_coder_text,
    cost_tier="paid",
    available_fn=check_qwen3_coder_available
)

