# tests/test_ai_provider.py
import os
import pytest
from unittest.mock import patch
from core.ai_provider import check_qwen3_coder_available, ROLE_PROVIDERS

@patch.dict(os.environ, {
    "VLLM_QWEN3_CODER_API_KEY": "test-key",
    "VLLM_QWEN3_CODER_BASE_URL": "https://example.com"
})
@patch("urllib.request.urlopen")
def test_qwen3_coder_available(mock_urlopen):
    assert check_qwen3_coder_available() is True
    mock_urlopen.assert_called_once()

@patch.dict(os.environ, {
    "VLLM_QWEN3_CODER_API_KEY": "",
    "VLLM_QWEN3_CODER_BASE_URL": "https://example.com"
})
def test_qwen3_coder_unavailable():
    assert check_qwen3_coder_available() is False

def test_role_providers_order():
    qwen3_index = [p["provider"] for p in ROLE_PROVIDERS].index("qwen3_coder_text")
    assert qwen3_index > [p["provider"] for p in ROLE_PROVIDERS].index("anthropic")
    assert qwen3_index < [p["provider"] for p in ROLE_PROVIDERS].index("claude")

# tests/test_llm_clients.py
import pytest
from unittest.mock import patch
from llm_clients import call_qwen3_coder_text

@patch("openai.OpenAI")
def test_qwen3_coder_call(mock_client):
    mock_client.return_value.chat.completions.create.return_value.choices[0].message.content = "Test response"
    
    result = call_qwen3_coder_text("What is 2+2?")
    assert result == "Test response"
    
    mock_client.assert_called_with(
        base_url="VLLM_QWEN3_CODER_BASE_URL",
        api_key="VLLM_QWEN3_CODER_API_KEY"
    )

@patch.dict(os.environ, {
    "VLLM_QWEN3_CODER_API_KEY": "",
    "VLLM_QWEN3_CODER_BASE_URL": ""
})
def test_qwen3_coder_missing_env():
    with pytest.raises(ValueError):
        call_qwen3_coder_text("What is 2+2?")